const PI: f64 = 3.141592653589793238;
const TWO_PI: f64 = PI * 2.0;
const DEF_ARC_TOLERANCE: f64 = 0.25;
const TOLERANCE: f64 = 1.0e-20;

/// Clipper's `Round`: half away from zero.
#[inline]
fn round(v: f64) -> i64 {
    if v < 0.0 {
        (v - 0.5) as i64
    } else {
        (v + 0.5) as i64
    }
}

fn area(poly: &[[i64; 2]]) -> f64 {
    let n = poly.len();
    if n < 3 {
        return 0.0;
    }
    let mut a = 0f64;
    let mut j = n - 1;
    for i in 0..n {
        a += (poly[j][0] as f64 + poly[i][0] as f64) * (poly[j][1] as f64 - poly[i][1] as f64);
        j = i;
    }
    -a * 0.5
}

fn unit_normal(p1: [i64; 2], p2: [i64; 2]) -> [f64; 2] {
    if p1 == p2 {
        return [0.0, 0.0];
    }
    let mut dx = (p2[0] - p1[0]) as f64;
    let mut dy = (p2[1] - p1[1]) as f64;
    let f = 1.0 / (dx * dx + dy * dy).sqrt();
    dx *= f;
    dy *= f;
    [dy, -dx]
}

/// Offsets the closed polygon `path` (float corners, truncated to integers like pyclipper) by
/// `delta` with round joins and returns the resulting polygons.
pub fn offset_closed_round(path: &[[f32; 2]], delta: f64) -> Vec<Vec<[i64; 2]>> {
    let path: Vec<[i64; 2]> = path.iter().map(|p| [p[0] as i64, p[1] as i64]).collect();

    // AddPath: strip duplicate points (and the closing duplicate)
    let mut high = path.len() as isize - 1;
    if high < 0 {
        return Vec::new();
    }
    while high > 0 && path[0] == path[high as usize] {
        high -= 1;
    }
    let mut src: Vec<[i64; 2]> = vec![path[0]];
    for p in &path[1..=high as usize] {
        if src.last() != Some(p) {
            src.push(*p);
        }
    }
    if src.len() < 3 {
        return Vec::new();
    }
    // FixOrientations
    if area(&src) < 0.0 {
        src.reverse();
    }

    // DoOffset
    if delta > -TOLERANCE && delta < TOLERANCE {
        return vec![src];
    }
    let y = if DEF_ARC_TOLERANCE > delta.abs() * DEF_ARC_TOLERANCE {
        delta.abs() * DEF_ARC_TOLERANCE
    } else {
        DEF_ARC_TOLERANCE
    };
    let mut steps = PI / (1.0 - y / delta.abs()).acos();
    if steps > delta.abs() * PI {
        steps = delta.abs() * PI;
    }
    let mut sin = (TWO_PI / steps).sin();
    let cos = (TWO_PI / steps).cos();
    let steps_per_rad = steps / TWO_PI;
    if delta < 0.0 {
        sin = -sin;
    }
    if delta <= 0.0 && src.len() < 3 {
        return Vec::new();
    }

    let len = src.len();
    let mut normals = Vec::with_capacity(len);
    for j in 0..len - 1 {
        normals.push(unit_normal(src[j], src[j + 1]));
    }
    normals.push(unit_normal(src[len - 1], src[0]));

    let mut dest: Vec<[i64; 2]> = Vec::new();
    let mut k = len - 1;
    for j in 0..len {
        // OffsetPoint(j, k, jtRound)
        let mut sin_a = normals[k][0] * normals[j][1] - normals[j][0] * normals[k][1];
        let at = |n: [f64; 2]| {
            [
                round(src[j][0] as f64 + n[0] * delta),
                round(src[j][1] as f64 + n[1] * delta),
            ]
        };
        if (sin_a * delta).abs() < 1.0 {
            let cos_a = normals[k][0] * normals[j][0] + normals[j][1] * normals[k][1];
            if cos_a > 0.0 {
                // angle => 0 degrees; Clipper returns here without advancing `k`
                dest.push(at(normals[k]));
                continue;
            }
        } else if sin_a > 1.0 {
            sin_a = 1.0;
        } else if sin_a < -1.0 {
            sin_a = -1.0;
        }
        if sin_a * delta < 0.0 {
            dest.push(at(normals[k]));
            dest.push(src[j]);
            dest.push(at(normals[j]));
        } else {
            // DoRound(j, k)
            let a = sin_a.atan2(normals[k][0] * normals[j][0] + normals[k][1] * normals[j][1]);
            let n = (round(steps_per_rad * a.abs()) as i32).max(1);
            let (mut x, mut y) = (normals[k][0], normals[k][1]);
            for _ in 0..n {
                dest.push([
                    round(src[j][0] as f64 + x * delta),
                    round(src[j][1] as f64 + y * delta),
                ]);
                let x2 = x;
                x = x * cos - sin * y;
                y = x2 * sin + y * cos;
            }
            dest.push(at(normals[j]));
        }
        k = j;
    }

    // Clipper::Execute(ctUnion, pftPositive) — for the simple convex polygons produced here this
    // only drops repeated and collinear vertices. Its output starts right after the top-most
    // (smallest y, then largest x) vertex; the start matters because `minAreaRect` breaks ties
    // between equally small rectangles by hull order.
    let mut cleaned = clean_polygon(dest);
    if cleaned.len() < 3 {
        return Vec::new();
    }
    let top = (0..cleaned.len())
        .min_by(|&a, &b| {
            let (pa, pb) = (cleaned[a], cleaned[b]);
            pa[1].cmp(&pb[1]).then(pb[0].cmp(&pa[0]))
        })
        .unwrap_or(0);
    let n = cleaned.len();
    cleaned.rotate_left((top + 1) % n);
    vec![cleaned]
}

fn clean_polygon(mut pts: Vec<[i64; 2]>) -> Vec<[i64; 2]> {
    loop {
        let n = pts.len();
        if n < 3 {
            return pts;
        }
        let mut removed = false;
        let mut out: Vec<[i64; 2]> = Vec::with_capacity(n);
        for i in 0..n {
            let prev = if out.is_empty() {
                pts[(i + n - 1) % n]
            } else {
                *out.last().unwrap()
            };
            let cur = pts[i];
            let next = pts[(i + 1) % n];
            let cross = (cur[0] - prev[0]) as i128 * (next[1] - cur[1]) as i128
                - (cur[1] - prev[1]) as i128 * (next[0] - cur[0]) as i128;
            if cur == prev || cross == 0 {
                removed = true;
                continue;
            }
            out.push(cur);
        }
        if !removed {
            return out;
        }
        pts = out;
    }
}
